<?php $this->start('page') ?>
<div class="row justify-content-center"><div class="col-xl-8"><div class="d-flex justify-content-between mb-4"><a href="/admin/payments" class="btn btn-outline-secondary"><i class="bi bi-arrow-left me-1"></i>Quay lại</a><span class="badge text-bg-<?= in_array($payment['status'], ['SUCCESS', 'COMPLETED'], true)?'success':'warning' ?> align-self-center fs-6"><?= $this->e(payment_status_label($payment['status'])) ?></span></div><div class="card border-0 shadow-sm rounded-4 p-4 p-lg-5"><h2 class="h4 fw-bold mb-4">Giao dịch #<?= (int)$payment['paymentId'] ?></h2><dl class="row"><dt class="col-sm-4">Đơn đặt</dt><dd class="col-sm-8"><a href="/admin/bookings/show/<?= (int)$payment['bookingId'] ?>">#<?= (int)$payment['bookingId'] ?></a></dd><dt class="col-sm-4">Khách hàng</dt><dd class="col-sm-8"><?= $this->e($payment['customerName']) ?> · <?= $this->e($payment['customerEmail']) ?></dd><dt class="col-sm-4">Tour</dt><dd class="col-sm-8"><?= $this->e($payment['tourTitle']) ?></dd><dt class="col-sm-4">Phương thức</dt><dd class="col-sm-8"><?= $this->e($payment['paymentMethod']) ?></dd><dt class="col-sm-4">Mã giao dịch</dt><dd class="col-sm-8 font-monospace"><?= $this->e($payment['transactionId'] ?: '—') ?></dd><dt class="col-sm-4">Số tiền</dt><dd class="col-sm-8 fw-bold text-danger fs-4"><?= number_format((float)$payment['amount'],0,',','.') ?>₫</dd><dt class="col-sm-4">Thời gian</dt><dd class="col-sm-8"><?= date('d/m/Y H:i',strtotime($payment['createdAt'])) ?></dd></dl><?php if($payment['status']==='PENDING'):?><form action="/admin/payments/confirm/<?= (int)$payment['paymentId'] ?>" method="POST" class="mt-3"><?= csrf_field() ?><button class="btn btn-success fw-bold"><i class="bi bi-check-circle me-1"></i>Xác nhận thanh toán</button></form><?php endif;?></div></div></div>
